package com.ppms.admin.service;
import com.ppms.admin.api.workforce.WorkforceDtos.*;import com.ppms.admin.domain.workforce.*;import com.ppms.admin.repositories.workforce.*;import com.ppms.shared.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class RosterService {private final RosterRepository rosters;private final DutyAssignmentRepository assignments;private final EmployeeRepository employees;private final ShiftTemplateRepository shifts;
@Transactional(readOnly=true)public List<RosterDto> list(UUID siteId,LocalDate weekStart){if(siteId!=null&&weekStart!=null)return rosters.findBySiteIdAndWeekStart(siteId,weekStart).stream().map(this::dto).toList();return(siteId==null?rosters.findAll():rosters.findBySiteId(siteId)).stream().map(this::dto).toList();}
@Transactional public RosterDto createDraft(RosterRequest r){if(r.weekStart().getDayOfWeek()!=DayOfWeek.MONDAY)throw new ValidationException("Roster weekStart must be a Monday");if(rosters.findBySiteIdAndWeekStart(r.siteId(),r.weekStart()).isPresent())throw new ValidationException("Roster already exists for site and week");Roster x=new Roster();x.setSiteId(r.siteId());x.setWeekStart(r.weekStart());return dto(rosters.save(x));}
@Transactional public RosterDto publish(UUID id,UUID userId){Roster r=find(id);r.setStatus(Roster.Status.PUBLISHED);r.setPublishedBy(userId);r.setPublishedAt(Instant.now());return dto(r);}
@Transactional public RosterDto bulkAssignments(UUID id,List<DutyAssignmentRequest> requests){Roster r=find(id);if(r.getStatus()==Roster.Status.PUBLISHED)throw new ValidationException("Published roster cannot be changed");assignments.deleteByRosterId(id);assignments.flush();Set<String> unique=new HashSet<>();for(DutyAssignmentRequest q:requests){if(q.date().isBefore(r.getWeekStart())||q.date().isAfter(r.getWeekStart().plusDays(6)))throw new ValidationException("Assignment date is outside roster week");if(!employees.existsById(q.employeeId()))throw new EntityNotFoundException("Employee",q.employeeId());if(!shifts.existsById(q.shiftTemplateId()))throw new EntityNotFoundException("ShiftTemplate",q.shiftTemplateId());if(!unique.add(q.employeeId()+":"+q.date()+":"+q.shiftTemplateId()))throw new ValidationException("Duplicate duty assignment");DutyAssignment a=new DutyAssignment();a.setRosterId(id);a.setEmployeeId(q.employeeId());a.setDate(q.date());a.setShiftTemplateId(q.shiftTemplateId());a.setSubUnitId(q.subUnitId());a.setRoleHint(q.roleHint());a.setNote(q.note());assignments.save(a);}return dto(r);}
@Transactional public RosterDto copyFromPreviousWeek(UUID id){Roster target=find(id);if(target.getStatus()==Roster.Status.PUBLISHED)throw new ValidationException("Published roster cannot be changed");Roster source=rosters.findBySiteIdAndWeekStart(target.getSiteId(),target.getWeekStart().minusWeeks(1)).orElseThrow(()->new ValidationException("Previous week roster not found"));List<DutyAssignmentRequest> copies=assignments.findByRosterId(source.getId()).stream().map(a->new DutyAssignmentRequest(a.getEmployeeId(),a.getDate().plusWeeks(1),a.getShiftTemplateId(),a.getSubUnitId(),a.getRoleHint(),a.getNote())).toList();return bulkAssignments(id,copies);}
private Roster find(UUID id){return rosters.findById(id).orElseThrow(()->new EntityNotFoundException("Roster",id));}private RosterDto dto(Roster r){return new RosterDto(r.getId(),r.getSiteId(),r.getWeekStart(),r.getStatus(),r.getPublishedBy(),r.getPublishedAt(),assignments.findByRosterId(r.getId()).stream().map(a->new DutyAssignmentDto(a.getId(),a.getEmployeeId(),a.getDate(),a.getShiftTemplateId(),a.getSubUnitId(),a.getRoleHint(),a.getNote())).toList());}}
